'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process');
const {parse,walk}=require('../audits/audit-i18n-global.cjs'),root=path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),base='d16f771d734f3273bd4ae0f3ef8610f295df07c9',old=f=>execFileSync('git',['show',base+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}),names=['showPostRequired','signalerRefusCout','signalerRefusPa'];
const cases=JSON.parse(read('outils/bancs/fixtures/refus-actions-cas-20261113.json')),sourceRows=JSON.parse(read('outils/audits/I18N-REFUS-ACTIONS-871-sources.json'));
const reuse=JSON.parse(read('outils/audits/I18N-REFUS-ACTIONS-871-reutilisation.json')),owned=new Set(reuse.ownedBodyKeys);
function selected(s){return parse(s).body.filter(n=>n.type==='FunctionDeclaration'&&names.includes(n.id.name)).map(n=>s.slice(n.start,n.end)).join('\n');}
function marker(n){const c=n.expression?.type==='ChainExpression'?n.expression.expression:n.expression;return n.type==='ExpressionStatement'&&c?.callee?.property?.name==='markToast'&&c.callee.object?.property?.name==='RPI18nPlateau'&&c.callee.object.object?.name==='globalThis';}
function clean(n){if(!n||typeof n!=='object')return n;if(marker(n))return null;if(Array.isArray(n))return n.map(clean).filter(x=>x!==null);const o={};for(const [k,v]of Object.entries(n))if(!['start','end','loc','raw'].includes(k))o[k]=clean(v);return o;}
function proof(){const p=path.join(root,'outils/audits/I18N-REFUS-ACTIONS-871-preuve.json');return fs.existsSync(p)?JSON.parse(fs.readFileSync(p)):null;}
function catalog(){const c={locale:'fr',RP_I18N_GAME_ENABLED:true};c.window=c;c.RPPlateauI18n={language:()=>c.locale};vm.createContext(c);for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/toast-resources.js','i18n/action-feedback-resources.js'])vm.runInContext(read(f),c);c.i18next.init({lng:'fr',fallbackLng:'fr',resources:c.RP_I18N_RESOURCES,initImmediate:false,interpolation:{escapeValue:false}});return c;}
test('refus : seize seules annotations, AST entier du core et logique métier inchangés',()=>{
 const p=proof(),s=p?execFileSync('git',['show',p.codeCommit+':plateau-core.js'],{cwd:root,encoding:'utf8',maxBuffer:4e6}):read('plateau-core.js');assert.deepEqual(clean(parse(s)),clean(parse(old('plateau-core.js'))));let count=0;walk(parse(s),n=>{if(marker(n))count++;});assert.equal(count,16);
 const current=selected(read('plateau-core.js'));for(const row of sourceRows.filter(r=>owned.has(r.key)))assert.ok(current.includes('actionFeedback.'+row.key),row.key);
 const ref=p?.codeCommit||execFileSync('git',['merge-base','HEAD','origin/main'],{cwd:root,encoding:'utf8'}).trim();assert.equal(execFileSync('git',['diff','--name-only',base,ref,'--','api','migrations','supabase','supabase.js','auth.js','data.js','plateau-politique.js','plateau-router.js','i18n/toast-resources.js'],{cwd:root,encoding:'utf8'}),'');
});
test('refus : cinq corps et un titre français exacts, quinze corps sans duplication, neuf langues et variables cohérentes',()=>{
 const c=catalog(),fr=c.RP_I18N_RESOURCES.fr.translation.actionFeedback;assert.equal(Object.keys(fr).length,6);assert.equal(sourceRows.length,20);for(const row of sourceRows)if(owned.has(row.key))assert.equal(fr[row.key],row.fr);else assert.equal(fr[row.key],undefined);assert.equal(fr.titleReserved,'Action réservée');
 const variables=s=>(s.match(/{{[^}]+}}/g)||[]).sort();for(const lang of ['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'])for(const key of [...sourceRows.filter(r=>owned.has(r.key)).map(r=>r.key),'titleReserved']){const value=c.RP_I18N_RESOURCES[lang].translation.actionFeedback[key];assert.ok(value.trim());assert.deepEqual(variables(value),variables(fr[key]),key+'/'+lang);if(lang!=='fr')assert.notEqual(value,fr[key]);}
 assert.equal(c.RPToastI18n.key('Action réservée'),'actionFeedback.titleReserved');for(const title of new Set(sourceRows.map(r=>r.title).filter(t=>t!=='Action réservée')))assert.ok(c.RPToastI18n.key(title).startsWith('toastTitles.'),title);
});
function run(example,before,withApi=true){
 const calls=[],toasts=[],annotations=[],c={state:{char:{country:example.country||'republic'},pa:3,arg:700,inventory:[{id:'fixture'}],progression:{stage:2}},COUNTRIES:{republic:{cur:'FR'},soviet:{cur:'PSK'}},console:{warn(){},error(){}},showToast:(...a)=>toasts.push(a),getFondsDisponiblesOrdinaires:()=>{calls.push('funds');return example.funds??45.5;}};if(example.withoutFundsHelper)delete c.getFondsDisponiblesOrdinaires;for(const f of ['fetch','sbRpc','deduireCoutOrdre'])c[f]=()=>{calls.push(f);throw Error('Appel métier interdit');};if(withApi)c.RPI18nPlateau={markToast:(...a)=>annotations.push(a)};const snapshot=JSON.stringify(c.state);vm.createContext(c);vm.runInContext(selected(before?old('plateau-core.js'):read('plateau-core.js')),c);c[example.function](...example.args);assert.equal(JSON.stringify(c.state),snapshot);return JSON.parse(JSON.stringify({calls,toasts,annotations}));
}
test('refus : 32 cas réels simulés, français identique, aucun paiement/PA/RPC et mêmes lectures de fonds',()=>{
 const c=catalog(),seen=new Set();assert.equal(cases.length,32);for(const example of cases){const before=run(example,true),after=run(example,false);assert.deepEqual(after.toasts,before.toasts,example.id);assert.deepEqual(after.calls,before.calls,example.id);assert.equal(after.toasts.length,1);assert.equal(after.annotations.length,1);const [key,fr,values,title]=after.annotations[0];assert.equal(key,owned.has(example.key)?'actionFeedback.'+example.key:reuse.reusedBodies.find(r=>r.sourceKey===example.key).key);assert.equal(fr,before.toasts[0][1]);assert.equal(title,before.toasts[0][0]);if(owned.has(example.key))assert.equal(c.i18next.t(key,{values}),fr,example.id);seen.add(example.key);assert.deepEqual(run(example,false,false).toasts,before.toasts);}
 assert.deepEqual([...seen].sort(),sourceRows.map(r=>r.key).sort());
});
test('refus : titres réutilisés intacts et repli français du corps paramétré',()=>{
 const c=catalog();for(const lang of ['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de']){c.locale=lang;c.i18next.changeLanguage(lang);for(const row of sourceRows)if(row.title!=='Action réservée')assert.equal(c.RPToastI18n.label(row.title),c.i18next.t(c.RPToastI18n.key(row.title)));}
 const d=JSON.parse(JSON.stringify(c.RP_I18N_RESOURCES.de.translation));delete d.actionFeedback.fundsRequired;c.i18next.removeResourceBundle('de','translation');c.i18next.addResourceBundle('de','translation',d);c.i18next.changeLanguage('de');assert.equal(c.i18next.t('actionFeedback.fundsRequired',{values:{required:'1 250',available:'45,5',currency:'PSK'}}),'1 250 PSK requis — vous disposez de 45,5 PSK.');
 assert.ok(read('plateau.html').indexOf('i18n/toast-resources.js')<read('plateau.html').indexOf('i18n/action-feedback-resources.js'));
});

test('refus : moteur inchangé hors compatibilité de markToast avec le corps déjà traduit',()=>{
 const p=proof(),source=p?execFileSync('git',['show',p.codeCommit+':i18n/plateau-init.js'],{cwd:root,encoding:'utf8'}):read('i18n/plateau-init.js');
 const normalize=n=>{if(!n||typeof n!=='object')return n;if(n.type==='FunctionDeclaration'&&n.id.name==='markToast')return null;if(Array.isArray(n))return n.map(normalize).filter(x=>x!==null);const o={};for(const [k,v]of Object.entries(n))if(!['start','end','loc','raw'].includes(k))o[k]=normalize(v);return o;};assert.deepEqual(normalize(parse(source)),normalize(parse(old('i18n/plateau-init.js'))));
});
